/**
 * MUJCODE Local Compiler — Agent Networking Protocol
 * 
 * Strict type contracts and schemas for agent-to-backend communication,
 * connection lifecycle states, pairing challenges, and execution job messages.
 */

import { ExecutionStatus } from './executionTypes.js';

export const AGENT_PROTOCOL_VERSION = '1.0.0';

/**
 * Explicit Connection State Machine States
 */
export type AgentConnectionStatus =
  | 'DISCONNECTED'
  | 'CONNECTING'
  | 'PAIRING_REQUIRED'
  | 'CONNECTED'
  | 'RECONNECTING'
  | 'ERROR'
  | 'STOPPING';

/**
 * Short-lived pairing challenge generated by the authenticated MUJCODE website
 */
export interface PairingChallenge {
  challengeCode: string;
  expiresAt: number; // Unix timestamp in ms
  studentDisplayName?: string;
  backendUrl: string;
}

/**
 * Pairing submission payload sent by the agent to the backend
 */
export interface PairingRequestPayload {
  protocolVersion: string;
  challengeCode: string;
  deviceId: string;
  deviceName: string;
  agentVersion: string;
  timestamp: number;
}

/**
 * Scoped device credential returned by the backend upon successful pairing
 */
export interface DeviceCredential {
  deviceId: string;
  deviceToken: string;
  userId: string;
  userDisplayName?: string;
  pairedAt: number;
  backendUrl: string;
}

/**
 * Safe pairing status representation exposed to the UI (contains no secrets)
 */
export interface SafePairingStatus {
  isPaired: boolean;
  deviceId: string | null;
  userDisplayName: string | null;
  pairedAt: number | null;
  backendUrl: string | null;
}

/**
 * Inbound code execution job message from the backend
 */
export interface InboundJobMessage {
  protocolVersion: string;
  jobId: string;
  languageId: number;
  sourceCode: string;
  stdin?: string;
  timeLimitMs?: number;
  timestamp: number;
  expiresAt?: number;
}

/**
 * Outbound code execution result message sent by the agent to the backend
 */
export interface OutboundJobResult {
  protocolVersion: string;
  jobId: string;
  status: ExecutionStatus;
  verdict: string;
  stdout: string;
  stderr: string;
  exitCode: number | null;
  executionTimeMs: number;
  compileError?: string | null;
  truncated: boolean;
  errorCode?: string | null;
  timestamp: number;
}

/**
 * Heartbeat ping sent periodically by the agent to verify connection liveness
 */
export interface HeartbeatPayload {
  protocolVersion: string;
  deviceId: string;
  agentVersion: string;
  timestamp: number;
  compilers: Record<string, boolean>;
}

/**
 * Heartbeat acknowledgement returned by the backend
 */
export interface HeartbeatAckPayload {
  protocolVersion: string;
  timestamp: number;
  serverTime: number;
}
